package types

// UserMessage is the unified user input for Prompt / Followup / Steer.
type UserMessage struct {
	// Message ID generated by Yao SDK (UUID), correlates with action.accepted/applied/rejected.
	ID string `json:"id"`

	// Message content (ACP ContentBlock array, supports text/image/audio/resource_link/resource).
	Content []ContentBlock `json:"content,omitempty"`

	// Convenience: plain text without constructing a ContentBlock.
	Message string `json:"message,omitempty"`

	// Attachment paths (unified path convention, see uri.md).
	Attachments []string `json:"attachments,omitempty"`
}

// ContentBlock is a message content unit (ACP v2 ContentBlock discriminated union).
// 6 standard types + custom extensions (Type prefixed with "_").
type ContentBlock struct {
	Type string `json:"type"` // "text" | "image" | "audio" | "resource_link" | "resource" | "_..."

	// text
	Text string `json:"text,omitempty"`

	// image (data+mimeType required, uri optional for provenance)
	Data     string `json:"data,omitempty"`     // base64 encoded
	MimeType string `json:"mimeType,omitempty"` // image: required; resource_link: optional
	URI      string `json:"uri,omitempty"`      // image: optional (provenance); resource_link: required

	// resource_link (uri+name required)
	Name        string `json:"name,omitempty"`
	Title       string `json:"title,omitempty"`
	Description string `json:"description,omitempty"`
	Icons       []Icon `json:"icons,omitempty"`
	Size        *int64 `json:"size,omitempty"` // file size in bytes

	// resource (nested EmbeddedResourcePayload)
	Resource *EmbeddedResourcePayload `json:"resource,omitempty"`

	// common
	Annotations *Annotations   `json:"annotations,omitempty"`
	Meta        map[string]any `json:"_meta,omitempty"`
}

// EmbeddedResourcePayload is an embedded resource (TextResourceContents | BlobResourceContents).
type EmbeddedResourcePayload struct {
	URI      string `json:"uri"`                // required
	MimeType string `json:"mimeType,omitempty"` // optional

	// Exactly one of Text or Blob must be set.
	Text string `json:"text,omitempty"`
	Blob string `json:"blob,omitempty"` // base64 encoded
}

// Icon is an ACP icon with size and theme.
type Icon struct {
	Src      string         `json:"src"`                // required, icon URI (format: uri)
	MimeType string         `json:"mimeType,omitempty"` // optional MIME type
	Sizes    []string       `json:"sizes,omitempty"`    // e.g. ["16x16", "32x32"]
	Theme    string         `json:"theme,omitempty"`    // "light" | "dark"
	Meta     map[string]any `json:"_meta,omitempty"`
}

// Annotations contains ACP standard content annotations.
type Annotations struct {
	Priority     *float64       `json:"priority,omitempty"`     // 0.0-1.0
	Audience     []string       `json:"audience,omitempty"`     // ["user"] | ["assistant"] | ["user","assistant"]
	LastModified string         `json:"lastModified,omitempty"` // RFC 3339
	Meta         map[string]any `json:"_meta,omitempty"`
}
